<?php
declare(strict_types=1);
require_once dirname(__DIR__,3).'/backyard_private/app/supporter.php';
$u=supporterRequire(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST') try {
    verifyCsrf();
    if(($_POST['action']??'')==='cheer') supporterCheer((int)$u['id'],(int)($_POST['runner']??0),(string)($_POST['message']??''));
    elseif(($_POST['action']??'')==='tip') supporterTip((int)$u['id'],(int)($_POST['runner']??0));
    redirect('supporter/index.php?saved=1');
} catch(Throwable $e) { $error=$e instanceof RuntimeException&&!($e instanceof PDOException)?$e->getMessage():'Aktion derzeit nicht möglich.'; }
$team=supporterTeam(); $score=supporterScore(); $week=supporterWeek();
$approved=array_map('intval',db()->query('SELECT runner_id FROM supporter_sharing')->fetchAll(PDO::FETCH_COLUMN));
$allApproved=count($team)===3 && count(array_intersect(array_column($team,'id'),$approved))===3;
$stats=[];
// Aggregate only explicitly approved runners. No activity details leave the server.
$q=db()->prepare("SELECT COUNT(a.id) runs,COALESCE(SUM(a.distance_m),0)/1000 km,COALESCE(SUM(FLOOR(GREATEST(a.distance_m,0)/6706)),0) loops,COALESCE(SUM(IF(a.activity_date>=?,a.distance_m,0)),0)/1000 week_km FROM activities a JOIN users u ON u.id=a.user_id JOIN supporter_sharing s ON s.runner_id=u.id WHERE u.id=? AND a.activity_date>=CONCAT(u.start_date,' 00:00:00') AND a.cache_updated_at>=UTC_TIMESTAMP()-INTERVAL 7 DAY");
foreach($team as $runner) if(in_array((int)$runner['id'],$approved,true)) { $q->execute([(new DateTimeImmutable('now',new DateTimeZone('UTC')))->modify('monday this week')->setTime(0,0)->format('Y-m-d H:i:s'),$runner['id']]); $stats[$runner['username']]=$q->fetch(); }
$cheers=db()->query('SELECT c.message,c.created_at,COALESCE(s.display_name,\'Ehemaliger Supporter\') sender,CONCAT(UPPER(LEFT(r.username,1)),SUBSTRING(r.username,2)) runner FROM supporter_cheers c LEFT JOIN supporters s ON s.id=c.supporter_id JOIN users r ON r.id=c.runner_id ORDER BY c.id DESC LIMIT 30')->fetchAll();
$q=db()->prepare('SELECT t.*,r.username,CONCAT(UPPER(LEFT(r.username,1)),SUBSTRING(r.username,2)) display_name FROM supporter_tips t JOIN users r ON r.id=t.runner_id WHERE supporter_id=? ORDER BY iso_year DESC,iso_week DESC LIMIT 104'); $q->execute([$u['id']]); $tips=$q->fetchAll();
$currentTip=null; foreach($tips as $tip) if((int)$tip['iso_year']===$week['year']&&(int)$tip['iso_week']===$week['week']) $currentTip=$tip;
supporterHead('Hallo '.$u['display_name'],$u); ?>
<?php if($error): ?><p role="alert"><?=h($error)?></p><?php endif; ?><?php if(isset($_GET['saved'])): ?><p role="status">Gespeichert!</p><?php endif; ?>
<p>Gemeinsam bis zum nächsten Loop. Aktuell: <?=h($week['key'])?> (Challenge-Zeit: UTC).</p>
<div class="support-grid"><?php foreach($team as $runner): $id=$runner['username']; $s=$stats[$id]??null; $b=$score['board'][$id]; ?><section class="panel"><h2><?=h($runner['display_name'])?></h2><?php if($s): ?><strong class="big"><?=h(percent((float)$s['km']))?> km</strong><p><?=h($s['runs'])?> Läufe · <?=h($s['loops'])?> vollständige Loops</p><p><?=h(percent((float)$s['week_km']))?> km diese Woche</p><p>Trainingsfortschritt im verfügbaren Cache</p><meter min="0" max="<?=h((string)max(1,...array_column($stats,'km')))?>" value="<?=h($s['km'])?>"><?=h($s['km'])?> km</meter><?php if($allApproved): $rank=array_search($id,array_column($score['ranking'],'username'),true); ?><p><?=h($b['points'])?> Challenge-Punkte · Platz <?=h($rank+1)?></p><?php endif; ?><small>Summen ab persönlichem Trainingsstart im gültigen Strava-Cache; kein vollständiges Kilometerarchiv.</small><?php else: ?><p>Trainingsdaten noch nicht für Supporter freigegeben.</p><?php endif; ?></section><?php endforeach; ?></div>
<section id="scoreboard" class="panel"><h2>Challenge-Scoreboard</h2><?php if($allApproved): $max=max(1,...array_column($score['ranking'],'points')); foreach($score['ranking'] as $i=>$r): ?><article class="score-row"><strong>#<?=h($i+1)?> <?=h($r['name'])?></strong><span><?=h($r['points'])?> Punkte · <?=h($r['bonus'])?> Bonus</span><meter min="0" max="<?=h($max)?>" value="<?=h($r['points'])?>"><?=h($r['points'])?></meter></article><?php endforeach; ?><p>Ein Punkt pro vollständigem Loop, fünf Bonuspunkte pro Wochensieg. Gleichstände erhalten jeweils den vollen Bonus.</p><h3>Loops der letzten zwölf erfassten Wochen</h3>
<?php $chartWeeks=array_reverse(array_slice($score['history'],0,12)); $chartMax=1; foreach($chartWeeks as $cw) foreach($cw['members'] as $m) $chartMax=max($chartMax,$m['loops']); ?>
<?php if($chartWeeks): ?><svg viewBox="0 0 640 220" role="img" aria-label="Vollständige Loops der letzten zwölf erfassten Wochen, Einzelwerte in der Wochenhistorie" style="display:block;width:100%;height:auto"><line x1="30" y1="185" x2="620" y2="185" stroke="#61758d"/><?php foreach($score['people'] as $id=>$person): $points=[]; foreach($chartWeeks as $ci=>$cw) { $x=30+$ci*580/max(1,count($chartWeeks)-1); $y=185-155*($cw['members'][$id]['loops']??0)/$chartMax; $points[]=round($x,2).','.round($y,2); } ?><polyline fill="none" stroke="<?=h($person['color'])?>" stroke-width="3" points="<?=h(implode(' ',$points))?>"/><?php foreach($chartWeeks as $ci=>$cw): $x=30+$ci*580/max(1,count($chartWeeks)-1); $y=185-155*($cw['members'][$id]['loops']??0)/$chartMax; ?><circle cx="<?=h($x)?>" cy="<?=h($y)?>" r="4" fill="<?=h($person['color'])?>"><title><?=h($person['name'].' '.$cw['week'].': '.($cw['members'][$id]['loops']??0).' Loops')?></title></circle><?php endforeach; endforeach; ?><text x="30" y="210" fill="#b4c3d2" font-size="12"><?=h($chartWeeks[0]['week'])?></text><text x="610" y="210" text-anchor="end" fill="#b4c3d2" font-size="12"><?=h($chartWeeks[count($chartWeeks)-1]['week'])?></text></svg><p>Orange: Tim · Türkis: Jonas · Violett: Noah</p><?php endif; ?><h3>Wochenhistorie</h3><?php foreach($score['history'] as $w): ?><details><summary><?=h($w['week'])?> · <?=$w['complete']?'Abgeschlossen':'Vorläufig'?></summary><?php foreach($score['people'] as $id=>$p): $loops=$w['members'][$id]['loops']??0; $win=in_array($id,$w['winners'],true); ?><p><?=h($p['name'])?>: <?=h($loops)?> Loops · Bonus <?=$win?5:0?> · <?=h($loops+($win?5:0))?> Punkte <?=$win?' · Wochensieger':''?></p><?php endforeach; ?></details><?php endforeach; else: ?><p>Das Team-Scoreboard erscheint nach Freigabe aller drei Läufer.</p><?php endif; ?></section>
<section id="cheers" class="panel"><h2>Anfeuern</h2><form method="post"><?php supporterField(); ?><input type="hidden" name="action" value="cheer"><label>Für wen?<select name="runner" required><?php foreach($team as $r): ?><option value="<?=h($r['id'])?>"><?=h($r['display_name'])?></option><?php endforeach; ?></select></label><label>Deine Nachricht<input name="message" required maxlength="240" list="motivation" placeholder="ONE MORE LOOP!"></label><datalist id="motivation"><?php foreach(['ONE MORE LOOP!','DU PACKST DAS!','STARKER LAUF!','WEITER SO!','NEVER GIVE UP!'] as $m): ?><option value="<?=h($m)?>"><?php endforeach; ?></datalist><small>Maximal 240 Zeichen. 30 Sekunden Pause zwischen Nachrichten. Für andere Supporter sichtbar.</small><button class="btn">Anfeuerung senden</button></form><h3>Letzte Anfeuerungen</h3><?php foreach($cheers as $c): ?><article class="cheer"><strong><?=h($c['sender'])?> → <?=h($c['runner'])?></strong><p><?=h($c['message'])?></p><small><?=h($c['created_at'])?> UTC</small></article><?php endforeach; ?></section>
<section id="tips" class="panel"><h2>Dein kostenloser Wochentipp</h2><p><?=h($week['key'])?> · Annahmeschluss: <?=h($week['deadline']->format('d.m.Y H:i'))?> UTC (Montag). <?=$week['open']?'Bis dahin änderbar.':'Tipps geschlossen.'?></p><p>Dein Tipp: <?=h($currentTip['display_name']??'Noch keiner')?>. Keine Einsätze oder Gewinne.</p><?php if($week['open']): ?><form method="post"><?php supporterField(); ?><input type="hidden" name="action" value="tip"><label>Wer gewinnt?<select name="runner" required><?php foreach($team as $r): ?><option value="<?=h($r['id'])?>" <?=($currentTip['runner_id']??0)==$r['id']?'selected':''?>><?=h($r['display_name'])?></option><?php endforeach; ?></select></label><button class="btn">Tipp speichern</button></form><?php endif; ?><h3>Deine Tipps</h3><?php foreach($tips as $tip): ?><p>KW <?=h($tip['iso_week'])?> / <?=h($tip['iso_year'])?> · <?=h($tip['display_name'])?> · <?=h(supporterTipStatus($tip,$score['history']))?></p><?php endforeach; ?><h3>Supporter-Highscore</h3><?php
// Derive correct predictions only from immutable finalized weeks, using shared tie rules.
$winners=[]; foreach($score['history'] as $w) if($w['complete']) $winners[$w['week']]=$w['winners'];
$high=db()->query("SELECT s.id,s.display_name,t.iso_year,t.iso_week,u.username FROM supporters s LEFT JOIN supporter_tips t ON t.supporter_id=s.id LEFT JOIN users u ON u.id=t.runner_id ORDER BY s.id")->fetchAll(); $scores=[];
foreach($high as $t) { $id=$t['id']; $scores[$id]??=['name'=>$t['display_name'],'points'=>0]; $k=sprintf('%04d-W%02d',$t['iso_year']??0,$t['iso_week']??0); if(in_array($t['username'],$winners[$k]??[],true)) $scores[$id]['points']++; }
usort($scores,static fn($a,$b)=>($b['points']<=>$a['points'])?:strcmp($a['name'],$b['name'])); foreach(array_slice($scores,0,20) as $i=>$s): ?><p>#<?=h($i+1)?> <?=h($s['name'])?> · <?=h($s['points'])?> richtige Tipps</p><?php endforeach; ?><small>Automatische Auswertung nach vollständiger Finalisierung. Jeder getippte Co-Sieger zählt; Wochen ohne Loops haben keinen Sieger.</small></section>
<?php supporterFoot(); ?>
